# Dois @font-face com data: URL (base64 sem quebra de linha: CSS nao aceita
# newline dentro de url()).
ui_dashboard_font_css() {
  printf "@font-face { font-family: 'DejaVu Sans Mono'; font-style: normal; font-weight: 400; font-display: block;\n  src: url(data:font/ttf;base64,"
  ui_dashboard_font_regular_b64 | tr -d '\n'
  printf ") format('truetype'); }\n"
  printf "@font-face { font-family: 'DejaVu Sans Mono'; font-style: normal; font-weight: 700; font-display: block;\n  src: url(data:font/ttf;base64,"
  ui_dashboard_font_bold_b64 | tr -d '\n'
  printf ") format('truetype'); }\n"
}

